export function getMoneyTopic(slug: string): MoneyTopic | undefined {
  return MONEY_TOPICS.find((t) => t.slug === slug);
}

export function getAllMoneyTopicPaths(): string[] {
  return MONEY_TOPICS.map((t) => `/topics/${t.slug}`);
}

